mod support;

use speedyspec_hooks::Value;
use speedyspec_wp_theme_json::php_json::decode;
use support::{assert_php_same as assert_php_eq, json, php_list, st};

fn base64(text: &str) -> Vec<u8> {
    const A: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = Vec::new();
    let mut buf = 0u32;
    let mut bits = 0;
    for c in text.bytes().filter(|c| *c != b'=') {
        buf = (buf << 6) | A.iter().position(|a| *a == c).unwrap() as u32;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push((buf >> bits) as u8);
        }
    }
    out
}

#[test]
fn file_cache_rereads_modified_file() {
    use speedyspec_wp_theme_json::resolver::files::FileCache;
    use speedyspec_wp_theme_json::{NoTranslation, RecordedDiagnostics};
    let dir = std::env::temp_dir().join(format!("theme-json-file-cache-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let file = dir.join("theme.json");
    let path = file.to_string_lossy().into_owned();
    let cache = FileCache::default();
    let notices = RecordedDiagnostics::default();
    std::fs::write(&file, r#"{"version":3,"title":"one"}"#).unwrap();
    assert_php_eq(
        &cache.read(&path, &notices, &NoTranslation),
        &json(r#"{"version":3,"title":"one"}"#),
    );
    std::fs::write(&file, r#"{"version":3,"title":"second"}"#).unwrap();
    assert_php_eq(
        &cache.read(&path, &notices, &NoTranslation),
        &json(r#"{"version":3,"title":"second"}"#),
    );
    std::fs::remove_dir_all(&dir).unwrap();
}

#[test]
fn json_comment_keys_removed() {
    let cleaned = speedyspec_wp_theme_json::resolver::remove_json_comments(json(
        r#"{"//":"c","a":{"//":"d","b":1},"c":[{"//":"e"}]}"#,
    ));
    assert_php_eq(&cleaned, &json(r#"{"a":{"b":1},"c":[[]]}"#));
}

#[test]
fn json_decode_0() {
    let actual = {
        let r = decode(&base64(
            "eyJhIjoxLCJiIjoyLjAsImMiOjFlMiwiZCI6LTAsImUiOjkyMjMzNzIwMzY4NTQ3NzU4MDcsImYiOjkyMjMzNzIwMzY4NTQ3NzU4MDgsImciOjEuNUUtM30=",
        ));
        match r {
            Ok(v) => php_list(vec![v, st("No error")]),
            Err(e) => php_list(vec![Value::Null, st(e.0)]),
        }
    };
    assert_php_eq(
        &actual,
        &json(
            r##"[{"a":1,"b":2.0,"c":100.0,"d":0,"e":9223372036854775807,"f":9.223372036854776e+18,"g":0.0015},"No error"]"##,
        ),
    );
}

